export function DataExport({
  format = "{{format}}",
  recordCount = {{recordCount}},
  includeHeaders = {{includeHeaders}},
  accent = "{{accent}}",
}) {
  const preBox = { background: "#24143010", padding: 10, borderRadius: 8, fontSize: 10, fontFamily: "ui-monospace, monospace", whiteSpace: "pre-wrap", margin: "0 0 12px" };
  let body;
  if (format === "csv") body = `${includeHeaders ? "id,name,total\n" : ""}1,Acme Co,4200\n2,Globex,1800`;
  else if (format === "json") body = `[${includeHeaders ? " \"__meta__\": true," : ""}\n  {"id":1,"name":"Acme Co"}]`;
  else body = `\uD83D\uDCC4 report-${recordCount}.pdf${includeHeaders ? "\n(cover page + headers)" : ""}`;
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700 }}>Export {recordCount} records</p>
      <pre style={preBox}>{body}</pre>
      <button type="button" style={{ border: "none", padding: "10px 16px", borderRadius: 8, fontWeight: 600, fontSize: 12, color: "#241430", cursor: "pointer", width: "100%", background: accent }}>Download .{format}</button>
    </div>
  );
}
